from math import gcd
from functools import reduce
from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal grid lines are rows largely made of one color.
    row_lines = []
    for r, row in enumerate(grid):
        color, count = Counter(row).most_common(1)[0]
        if count >= 0.65 * w:
            row_lines.append(r)

    if len(row_lines) < 2:
        return [row[:] for row in grid]

    sep_color = Counter(
        Counter(grid[r]).most_common(1)[0][0] for r in row_lines
    ).most_common(1)[0][0]

    # Vertical grid lines are identified by their values on horizontal lines.
    col_lines = []
    for c in range(w):
        if sum(grid[r][c] == sep_color for r in row_lines) >= len(row_lines) * 0.55:
            col_lines.append(c)

    if len(col_lines) < 2:
        return [row[:] for row in grid]

    def spacing(lines):
        diffs = [b - a for a, b in zip(lines, lines[1:])]
        return reduce(gcd, diffs)

    rp, cp = spacing(row_lines), spacing(col_lines)
    if rp <= 0 or cp <= 0:
        return [row[:] for row in grid]

    marks = [
        (r, c, grid[r][c])
        for r in row_lines for c in col_lines
        if grid[r][c] != sep_color
    ]
    if not marks:
        return [row[:] for row in grid]

    r0, r1 = min(x[0] for x in marks), max(x[0] for x in marks)
    c0, c1 = min(x[1] for x in marks), max(x[1] for x in marks)
    rs = list(range(r0, r1, rp))
    cs = list(range(c0, c1, cp))

    # The color filling the grid's ordinary cells is the output default.
    ordinary = [
        grid[r][c] for r in range(h) for c in range(w)
        if r not in row_lines and c not in col_lines
    ]
    default = Counter(ordinary).most_common(1)[0][0] if ordinary else sep_color

    out = [[default for _ in cs] for _ in rs]
    for i, r in enumerate(rs):
        for j, c in enumerate(cs):
            if grid[r][c] != sep_color:
                out[i][j] = grid[r][c]
    return out
